/**
 * Unit tests for the tool-result compaction module.
 *
 * Focus: pure-function correctness, context isolation across concurrent
 * requests, ref round-trip via `resolveRef`, and the message-walker path
 * for loaded history.
 */
import { describe, expect, it } from 'vitest';
import {
	compactToolResult,
	compactToolResults,
	DEFAULT_BUDGET,
	projectSummary,
	resolveRef,
	runWithCompaction,
} from './compact';

describe('projectSummary', () => {
	it('returns strings unchanged when below budget', () => {
		expect(projectSummary('hello', 100)).toBe('hello');
	});

	it('truncates oversized strings with an ellipsis', () => {
		const result = projectSummary('a'.repeat(20), 5);
		expect(result).toBe('aaaaa…');
	});

	it('serializes non-strings via JSON', () => {
		const result = projectSummary({ a: 1, b: 'x' }, 100);
		expect(result).toBe('{"a":1,"b":"x"}');
	});

	it('truncates serialized objects that exceed budget', () => {
		const big = { items: Array.from({ length: 50 }, (_, i) => ({ id: i, name: `item_${i}` })) };
		const result = projectSummary(big, 30);
		expect(result.length).toBe(31); // 30 chars + ellipsis
		expect(result.endsWith('…')).toBe(true);
	});
});

describe('compactToolResult', () => {
	it('is a no-op outside a compaction context', () => {
		const value = { huge: 'x'.repeat(10_000) };
		expect(compactToolResult('any', value)).toBe(value);
	});

	it('returns the value unchanged when under budget', () => {
		runWithCompaction(DEFAULT_BUDGET, () => {
			const value = { small: 'ok' };
			expect(compactToolResult('desk_list_files', value)).toBe(value);
		});
	});

	it('replaces oversized results with a ref projection', () => {
		runWithCompaction({ maxChars: 100, summaryChars: 40 }, () => {
			const value = { rows: 'x'.repeat(500) };
			const compacted = compactToolResult('desk_read_file', value) as {
				ref: string;
				summary: string;
				truncated: true;
				originalBytes: number;
				hint: string;
			};
			expect(compacted.truncated).toBe(true);
			expect(compacted.ref).toMatch(/^tr_desk_read_file_\d+$/);
			expect(compacted.summary.length).toBeLessThanOrEqual(41); // 40 + ellipsis
			expect(compacted.originalBytes).toBeGreaterThan(100);
			expect(compacted.hint).toContain(compacted.ref);
		});
	});

	it('stores the full value so resolveRef returns it', () => {
		runWithCompaction({ maxChars: 50, summaryChars: 20 }, () => {
			const value = { payload: 'a'.repeat(200) };
			const compacted = compactToolResult('tool_x', value) as { ref: string };
			expect(resolveRef(compacted.ref)).toBe(value);
		});
	});

	it('increments the ref counter across multiple compactions', () => {
		runWithCompaction({ maxChars: 10, summaryChars: 5 }, () => {
			const a = compactToolResult('t', { x: 'a'.repeat(100) }) as { ref: string };
			const b = compactToolResult('t', { x: 'b'.repeat(100) }) as { ref: string };
			expect(a.ref).not.toBe(b.ref);
			expect(a.ref).toMatch(/_0$/);
			expect(b.ref).toMatch(/_1$/);
		});
	});
});

describe('resolveRef', () => {
	it('returns undefined outside a compaction context', () => {
		expect(resolveRef('tr_anything_0')).toBeUndefined();
	});

	it('returns undefined for unknown refs', () => {
		runWithCompaction(DEFAULT_BUDGET, () => {
			expect(resolveRef('tr_does_not_exist_99')).toBeUndefined();
		});
	});
});

describe('runWithCompaction context isolation', () => {
	it('keeps refs scoped to each top-level run', () => {
		const refA = runWithCompaction({ maxChars: 5, summaryChars: 2 }, () => {
			return (compactToolResult('t', { big: 'aaaaaaaaaa' }) as { ref: string }).ref;
		});
		// Outside the run, the ref is gone.
		expect(resolveRef(refA)).toBeUndefined();
	});

	it('nested calls reuse the outer context', () => {
		runWithCompaction({ maxChars: 5, summaryChars: 2 }, () => {
			const outer = compactToolResult('t', { big: 'aaaaaaaaaa' }) as { ref: string };
			runWithCompaction(DEFAULT_BUDGET, () => {
				// Inner reuses outer context, so the outer ref is still resolvable.
				expect(resolveRef(outer.ref)).toBeDefined();
			});
		});
	});
});

describe('compactToolResults (message walker)', () => {
	it('leaves non-tool messages untouched', () => {
		const messages = [
			{ role: 'user', content: 'hi' },
			{ role: 'assistant', content: 'hello' },
		] as never[];
		expect(compactToolResults(messages)).toEqual(messages);
	});

	it('compacts oversized tool-result parts inside tool messages', () => {
		runWithCompaction({ maxChars: 50, summaryChars: 20 }, () => {
			const input = [
				{
					role: 'tool',
					content: [
						{
							type: 'tool-result',
							toolCallId: 'call_1',
							toolName: 'desk_read_file',
							output: { rows: 'x'.repeat(500) },
						},
					],
				},
			] as never[];
			const out = compactToolResults(input);
			const part = (out[0] as unknown as { content: Array<{ output: { truncated?: boolean; ref?: string } }> })
				.content[0];
			expect(part.output.truncated).toBe(true);
			expect(part.output.ref).toBeDefined();
		});
	});

	it('leaves small tool-result parts untouched', () => {
		runWithCompaction(DEFAULT_BUDGET, () => {
			const input = [
				{
					role: 'tool',
					content: [
						{
							type: 'tool-result',
							toolCallId: 'call_1',
							toolName: 'desk_list_files',
							output: { files: [] },
						},
					],
				},
			] as never[];
			const out = compactToolResults(input);
			expect(out).toEqual(input);
		});
	});
});

files.src/lib/server/ai/loop/compact.ts:
/**
 * Tool-result compaction — works around AI SDK #9631.
 *
 * AI SDK v6's `prepareStep` mutation to `messages` is silently dropped on
 * subsequent iterations ("by design" per maintainer). Trying to compact
 * oversized tool results inside `prepareStep` looks like it's working but
 * the SDK re-reads the original `response.messages` accumulator each step.
 *
 * Correct pattern: compact tool results at **execute time** by wrapping
 * each tool's `execute` return value. Oversized results are stored in a
 * request-scoped `refs` map and replaced in the model's view with a
 * `{ ref, summary, truncated, originalBytes }` projection. The model
 * can pull the full value back via the `resolve_ref` tool when needed.
 *
 * Storage lives in an `AsyncLocalStorage` context established by the
 * orchestrator around each request, so concurrent requests never
 * collide on refs.
 */
import { AsyncLocalStorage } from 'node:async_hooks';
import type { ModelMessage } from 'ai';

export interface CompactionBudget {
	/** Maximum serialized length (chars) a tool result may reach before compaction kicks in. */
	maxChars: number;
	/** Length (chars) of the summary preview embedded in the projected form. */
	summaryChars: number;
}

export const DEFAULT_BUDGET: CompactionBudget = {
	maxChars: 2000,
	summaryChars: 400,
};

/** Per-request compaction state. */
interface CompactionState {
	budget: CompactionBudget;
	refs: Map<string, unknown>;
	/** Monotonic ref counter so refs are readable (`tr_0`, `tr_1`, …). */
	counter: number;
}

const compactionContext = new AsyncLocalStorage<CompactionState>();

/** Establish a compaction context for the duration of `fn`. Nested calls reuse the outer context. */
export function runWithCompaction<T>(budget: CompactionBudget, fn: () => T): T {
	const existing = compactionContext.getStore();
	if (existing) return fn();
	const state: CompactionState = { budget, refs: new Map(), counter: 0 };
	return compactionContext.run(state, fn);
}

/** Retrieve the full value behind a ref, or `undefined` if the ref is unknown. */
export function resolveRef(ref: string): unknown {
	const state = compactionContext.getStore();
	if (!state) return undefined;
	return state.refs.get(ref);
}

/** Shape emitted in place of an oversized tool result. */
export interface CompactedResult {
	ref: string;
	summary: string;
	truncated: true;
	originalBytes: number;
	/**
	 * Hint for the model: use the `resolve_ref` tool with this ref to pull the full value
	 * if you need more detail than the summary provides.
	 */
	hint: string;
}

/** Serialize a value to a stable length estimate. */
function serializedLength(value: unknown): number {
	try {
		return JSON.stringify(value)?.length ?? 0;
	} catch {
		return 0;
	}
}

/** Generate a human-readable preview of a value, capped at `maxChars`. */
export function projectSummary(value: unknown, maxChars: number): string {
	let text: string;
	try {
		text = typeof value === 'string' ? value : JSON.stringify(value);
	} catch {
		text = '[unserializable]';
	}
	if (text.length <= maxChars) return text;
	return `${text.slice(0, maxChars)}…`;
}

/**
 * Compact a single tool-result value. Returns the projected form if the value
 * exceeds the budget, otherwise returns the value unchanged. Does nothing if
 * no compaction context is active.
 */
export function compactToolResult(toolName: string, value: unknown): unknown {
	const state = compactionContext.getStore();
	if (!state) return value;
	const length = serializedLength(value);
	if (length <= state.budget.maxChars) return value;

	const ref = `tr_${toolName}_${state.counter++}`;
	state.refs.set(ref, value);
	const projected: CompactedResult = {
		ref,
		summary: projectSummary(value, state.budget.summaryChars),
		truncated: true,
		originalBytes: length,
		hint: `Full result stored as ref "${ref}". Call resolve_ref with this ref if you need more detail.`,
	};
	return projected;
}

/**
 * Walk a message array and compact any oversized tool-result content parts.
 * Used for **loaded history** (resumed conversations) where large tool
 * results already sit in the message array before `streamText` runs.
 *
 * Pure function — does not touch compaction context. Returns a new array;
 * the input is not mutated. When a compaction context is active, refs are
 * stored there so the model can resolve them.
 */
export function compactToolResults(messages: ModelMessage[]): ModelMessage[] {
	return messages.map((msg) => {
		if (msg.role !== 'tool') return msg;
		// AI SDK v6 tool message content is an array of tool-result parts.
		const content = (msg as unknown as { content: unknown }).content;
		if (!Array.isArray(content)) return msg;
		const nextContent = content.map((part: unknown) => {
			if (!part || typeof part !== 'object') return part;
			const p = part as Record<string, unknown>;
			if (p.type !== 'tool-result') return part;
			const output = p.output;
			const compacted = compactToolResult((p.toolName as string) ?? 'unknown', output);
			if (compacted === output) return part;
			return { ...p, output: compacted };
		});
		return { ...msg, content: nextContent } as ModelMessage;
	});
}

